%[text] # Verify Tone Transmitter Algorithm Using MATLAB
%[text] Use the modified host interface script to:
%[text] - Set up the radio device.
%[text] - Configure the Device Under Test (DUT).
%[text] - Transmit a test tone.
%[text] - Check the transmitted frequency in MATLAB to verify that the tone transmitter is working correctly. \
%[text] ### Initial Setup 
savedRadioConfigurations = radioConfigurations;
savedRadioConfigurationNames = string({savedRadioConfigurations.Name});
radioConfig = savedRadioConfigurationNames(1) ; %[control:dropdown:8621]{"position":[15,46]} %[control:button:3e1a]{"position":[46,47]}
transmitAntennas = hTransmitAntennas(radioConfig);
receiveAntennas = hCaptureAntennas(radioConfig);
%%
%[text] ### Create Radio Object
radio = radioConfigurations(radioConfig);
hDevice = usrp(radio);
%%
%[text] # Task \#1 Program FPGA
%[text] - Enable Load Bitstream to program the FPGA.
%[text] - Update the script with the bitstream and device tree files.
%[text] - Find these file paths in the generated host interface script.
%[text] - For USRP X310, only the bitstream file is needed. \
%[text] Function: programFPGA
%[text]  Inputs:
%[text] 1. hDevice - USRP device object
%[text] 2. Path to the generated bitstream file
%[text] 3. Path to the generated device tree file (Not applicable for X310) \
%[text] Result: The FPGA is programmed with the generated design
% Write your code here         

%%
%[text] # Task \#2 Configure the DUT interfaces
%[text] - It reads the hand-off file and automatically sets up the DUT connections.
%[text] - It also sets default values for Sample Rate, DUT Output Antennas, and DUT Input Antennas based on your Simulink model settings. \
%[text] Function: describeFPGA
%[text]  Inputs:
%[text] 1. hDevice - USRP device object
%[text] 2. Path to the generated hand-off information file \
%[text] Result: The DUT interfaces are configured automatically based on the HDL design and Simulink model settings.
% Write your code here

%%
%[text] ## Configure Device
hDevice.TransmitCenterFrequency = 2450000000; %[control:editfield:9d96]{"position":[35,45]}
hDevice.ReceiveCenterFrequency = 2450000000; %[control:editfield:0d75]{"position":[34,44]}
hDevice.TransmitRadioGain =10; %[control:editfield:84c1]{"position":[28,30]}
hDevice.ReceiveRadioGain =10; %[control:editfield:1560]{"position":[27,29]}
hDevice.DUTOutputAntennas = transmitAntennas(1); %[control:dropdown:8eb7]{"position":[29,48]}
hDevice.CaptureAntennas = receiveAntennas(1); %[control:dropdown:70d3]{"position":[27,45]}
hDevice.LoopbackMode ="FPGA";
%%
%[text] # Task \#3 Create and Set Up FPGA Object
%[text] To connect to the DUT on the FPGA of your radio with MATLAB, create an `fpga` object with your `usrp` System object.
hFPGA = fpga(hDevice);
%[text] Call your autogenerated setup function and pass hFPGA as argument 
% Write your code here

%[text] 
setup(hDevice);
%%
%[text] ## Configure and Start DUT
%[text] Use the `writePort` function to configure the tone transmitter DUT on the FPGA.
%[text] Set the NCO tone frequency.
toneFrequency = 10000000;% In Hz %[control:editfield:9004]{"position":[17,25]}
inc = round(single(toneFrequency)/single(hDevice.SampleRate)*2^16);
%[text] # Task\#4 Write Registers and enable and configure the DUT
%[text] Function: writePort
%[text] Parameters:
%[text] 1. hFPGA - FPGA interface object
%[text] 2. DUT configuration register name for phase increment
%[text] 3. Value of Phase increment  \
%[text] 
% Write your code here

%[text] Function: writePort
%[text] Parameters:
%[text] 1. hFPGA - FPGA interface object
%[text] 2. DUT reset control register name
%[text] 3. false \
% Write your code here

%[text] Function: writePort
%[text] Parameters:
%[text] 1. hFPGA - FPGA interface object
%[text] 2. DUT enable register name
%[text] 3. true \
% Write your code here

%[text] 
pause(0.5);
%%
%[text] ## Capture and Verify Output
%[text] 
%[text]{"align":"center"} ![](text:image:4a09)
hDevice(50000);
numSamples = 50000;
data = hDevice.capture(numSamples);
specAn = spectrumAnalyzer(SampleRate = hDevice.SampleRate, ...
    ChannelNames = ["Received waveform"], ...
    ShowLegend = true);
specAn(data);
pause(0.1);
%%
%[text] # Task\#5 Write Registers to reset and disable the DUT
%[text] Function: writePort
%[text] Parameters:
%[text] 1. hFPGA - FPGA interface object
%[text] 2. DUT reset control register name
%[text] 3. false \
% Write your code here

%[text] Function: writePort
%[text] Parameters:
%[text] 1. hFPGA - FPGA interface object
%[text] 2. DUT enable register name
%[text] 3. true \
% Write your code here

%[text] Release the hardware objects.
release(hFPGA);
release(hDevice);
